/**
 * Typed access to the level data generated by tools/generate_levels.py.
 * Never edit levels.json by hand — re-run the Python generator instead.
 */
import raw from './levels.json';

export const KIND = {
  NORMAL: 0,
  SLOW: 1,
  GOLDEN: 2,
  RAINBOW: 3,
  BOMB: 4,
} as const;
export type BallKind = (typeof KIND)[keyof typeof KIND];

/** [spawnTime, kind, color, x, speedMul, driftAmp, driftFreq] */
export type BallSpawn = [number, BallKind, number, number, number, number, number];

export type BonusType = 'perfect' | 'golden' | 'combo' | 'rainbow';

export type IntroKey =
  | 'basics'
  | 'three_colors'
  | 'golden'
  | 'slow'
  | 'rainbow'
  | 'bomb'
  | 'rush'
  | 'drift'
  | 'pairs'
  | 'triples';

export interface LevelConfig {
  id: number;
  world: number;
  target: number;
  lives: number;
  maxMistakes: number;
  fallSpeed: number;
  spawnInterval: number;
  colors: number[];
  obstacleProb: number;
  bonus: { type: BonusType; count: number };
  intro: IntroKey | null;
  loopAfter: number;
  duration: number;
  balls: BallSpawn[];
}

export interface Geometry {
  fieldW: number;
  fieldH: number;
  ballR: number;
  compW: number;
  wallT: number;
  trayRimY: number;
  trayFloorY: number;
  spawnY: number;
  gravity: number;
  startSpeedFactor: number;
}

export interface WorldInfo {
  id: number;
  name: string;
  first: number;
  last: number;
}

interface LevelFile {
  version: number;
  geometry: Geometry;
  worlds: WorldInfo[];
  levels: LevelConfig[];
}

const data = raw as unknown as LevelFile;

export const GEOMETRY: Geometry = data.geometry;
export const WORLDS: WorldInfo[] = data.worlds;
export const LEVELS: LevelConfig[] = data.levels;
export const LEVEL_COUNT = LEVELS.length;

export const TRAY_W = GEOMETRY.compW * 3;
export const TRAY_C_MAX = (GEOMETRY.fieldW - TRAY_W) / 2;
/** compartment x offsets from tray centre: red, blue, yellow */
export const COLOR_OFFSET = [-GEOMETRY.compW, 0, GEOMETRY.compW];

export function getLevel(id: number): LevelConfig {
  return LEVELS[Math.max(0, Math.min(LEVELS.length - 1, id - 1))];
}

export function worldOf(id: number): WorldInfo {
  return WORLDS.find((w) => id >= w.first && id <= w.last) ?? WORLDS[0];
}

export const INTRO_TEXT: Record<IntroKey, { title: string; body: string }> = {
  basics: { title: 'Drag to move', body: 'Slide one finger left and right below the tray, so you can always see the balls. Catch each ball in the compartment of the same color.' },
  three_colors: { title: 'Three colors', body: 'Red, blue and yellow now. Keep an eye on which compartment is under each ball.' },
  golden: { title: 'Golden coins', body: 'Spinning golden coins fit ANY compartment — catch them for bonus coins. Missing one costs nothing.' },
  slow: { title: 'Slow balls', body: 'Balls with a white ring fall slowly. Do not let them trick your timing.' },
  rainbow: { title: 'Rainbow balls', body: 'Rainbow balls fit every compartment and count toward your goal.' },
  bomb: { title: 'Bombs!', body: 'Dark bombs must be avoided. Move the tray out of their way.' },
  rush: { title: 'Speed rush', body: 'Sometimes a short burst of faster balls arrives. Stay calm.' },
  drift: { title: 'Drifting bombs', body: 'Some bombs sway from side to side while they fall.' },
  pairs: { title: 'Double drops', body: 'Two balls can land together. Line up both compartments at once.' },
  triples: { title: 'Triple drops', body: 'Red, blue and yellow side by side — catch all three in one move.' },
};

export const BONUS_TEXT: Record<BonusType, (n: number) => string> = {
  perfect: () => 'No mistakes',
  golden: (n) => `Catch ${n} golden coins`,
  combo: (n) => `Reach a ${n} combo`,
  rainbow: (n) => `Catch ${n} rainbow`,
};
